lueurs.reducer:
(
  $s := $state;
  $a := $action;
  $t := $a.type;
  $P := $a.payload;
  $now := $a.t;
  $COL := {"p0": "#fbbf24", "p1": "#2dd4bf", "p2": "#f472b6", "p3": "#a5b4fc"};
  $UP := [
    {"id": "banc", "nom": "Banc nombreux", "desc": "+15 poissons lumineux"},
    {"id": "lueur", "nom": "Grande lueur", "desc": "Vision +2 cases"},
    {"id": "ample", "nom": "Éclat ample", "desc": "L'éclat repousse deux fois plus loin"},
    {"id": "rapide", "nom": "Éclat rapide", "desc": "Recharge de l'éclat −30 %"},
    {"id": "vif", "nom": "Poissons vifs", "desc": "Le banc nage 20 % plus vite"},
    {"id": "leurre", "nom": "Leurre", "desc": "Une méduse-leurre par niveau (E ou B)"},
    {"id": "sonar", "nom": "Sonar", "desc": "Sortie et trésors visibles d'avance"},
    {"id": "carapace", "nom": "Carapace", "desc": "Le premier poisson perdu par niveau revient"}
  ];
  $SIZES := [[44, 30], [50, 33], [54, 36], [58, 38], [62, 40], [66, 44], [70, 46], [76, 50]];
  $REEF := [
    "..............",
    "..##......#...",
    ".####....###..",
    "..###.....#...",
    "...#...##.....",
    "......####....",
    ".......##.....",
    "..#...........",
    ".###.....##...",
    "..#.....####..",
    ".........##...",
    ".............."
  ];
  $tier := function($l) {
    $l <= 3
      ? {"kind": "grotte", "nom": "Grotte", "rock": "#292524", "water": "#0c4a6e", "fill": 0.44}
      : $l <= 6
        ? {"kind": "recif", "nom": "Récif", "rock": "#7c2d12", "water": "#0e7490", "fill": 0.42}
        : {"kind": "abysse", "nom": "Abysse", "rock": "#1e1b4b", "water": "#082f49", "fill": 0.43}
  };
  $center := function($c) { [$c[0] * 32 + 16, $c[1] * 32 + 16] };
  $cellOf := function($p) { [$floor($p[0] / 32), $floor($p[1] / 32)] };
  $dist := function($u, $v) { $sqrt(($u[0] - $v[0]) * ($u[0] - $v[0]) + ($u[1] - $v[1]) * ($u[1] - $v[1])) };
  $names := function($n) { [$map([0 .. ($n - 1)], function($i) { "p" & $i })] };
  $blank := function($w, $h, $c) { $map([1 .. $h], function() { $pad("", $w, $c) }) };
  $rect := function($c, $r) { [$c[0] * 32 + 16 - $r, $c[1] * 32 + 16 - $r, $c[0] * 32 + 16 + $r, $c[1] * 32 + 16 + $r] };

  /* niveau : grille, départ, sortie, trésors, zones d'apparition */
  $mkLevel := function($s) {(
    $lvl := $s.level;
    $sz := $SIZES[$lvl - 1];
    $W := $sz[0];
    $H := $sz[1];
    $seed := $s.seed * 31 + $lvl * 7919;
    $tr := $tier($lvl);
    $raw := $tr.kind = "recif"
      ? $genWfc($REEF, $W, $H, $seed, {"tries": 12, "wrapSample": true})
      : $genCave($W, $H, $seed, {"fill": $tr.fill, "steps": 4});
    $rows := $tr.kind = "recif"
      ? (
          $big := $gridRegions($raw, {"values": "."})[0];
          $gridSet($blank($W, $H, "#"), $gridFlood($raw, $big.at), ".")
        )
      : $raw;
    $sol := $gridFind($rows, ".");
    $minx := $min($map($sol, function($c) { $c[0] }));
    $start := $filter($sol, function($c) { $c[0] = $minx })[0];
    /* toutes les cases atteignables et leur distance au départ, en un appel */
    $cells := [$map($gridReach($rows, $start, 1000000), function($r) { {"c": [$r[0], $r[1]], "d": $r[2], "k": $r[0] & "," & $r[1]} })];
    $dist0 := $merge($map($cells, function($o) { {$o.k: $o.d} }));
    $dAt := function($c) { $lookup($dist0, $c[0] & "," & $c[1]) };
    $maxD := $max($cells.d);
    $exit := $cells[d = $maxD][0].c;
    $far := $cells[d >= $maxD * 0.55][0].c;
    $far2 := $cells[d >= $maxD * 0.8][0].c;
    $pts := $genPoisson($W, $H, 5, $seed + 1);
    $tre := $filter($map($pts, function($p) { {"c": [$floor($p[0]), $floor($p[1])]} }), function($o) {
      $dAt($o.c) >= 12 and $dist($o.c, $exit) > 3
    });
    $treasures := $map([0 .. $min([$count($tre) - 1, 2 + $lvl])], function($i) { {"id": $lvl * 100 + $i, "c": $tre[$i].c} });
    $merge([$s, {
      "rows": $rows, "W": $W, "H": $H, "start": $start, "exit": $exit, "far": $far, "far2": $far2,
      "treasures": [$treasures], "explored": $blank($W, $H, "0"), "lastCell": {}, "fogT": 0, "dirty": true,
      "taps": {}, "carapaceUsed": false, "leurres": $s.mods.leurre, "leurre": null, "eclat": {"until": 0, "ready": {}},
      "tierNom": $tr.nom
    }])
  )};

  /* description de l'essaim pour le niveau */
  $spec := function($s) {(
    $lvl := $s.level;
    $vif := 1 + 0.2 * $s.mods.vif;
    {
      "bounds": [0, 0, $s.W * 32, $s.H * 32],
      "edges": "steer",
      "seed": $s.seed + $lvl,
      "grid": {"rows": $s.rows, "cell": 32},
      "groups": [
        {"name": "p", "prefix": "p", "count": $s.players, "maxSpeed": 150, "maxForce": 900, "radius": 10, "view": 40,
         "separation": 0.6, "arrive": {"target": "dp:lueurs.cibles.{name}", "radius": 40, "weight": 3}, "spawn": $rect($s.start, 14)},
        {"name": "f", "prefix": "f", "count": $s.fish, "maxSpeed": 165 * $vif, "maxForce": 520, "radius": 4, "view": 34,
         "separation": 1.5, "alignment": 0.7, "cohesion": 0.5, "wander": 0.25,
         "follow": {"target": "group:p", "radius": 230, "swap": 55, "slow": 50, "weight": 1.8, "colors": $COL, "lost": "#475569"},
         "evade": {"target": "group:r", "radius": 120, "weight": 2.6}, "flee": {"target": "group:a", "radius": 90, "weight": 2.2},
         "spawn": $rect($s.start, 40)},
        {"name": "r", "prefix": "r", "count": [1, 1, 2, 2, 3, 3, 4, 4][$lvl - 1], "maxSpeed": 85 + $lvl * 6, "maxForce": 260, "radius": 15, "view": 70,
         "separation": 1.2, "flow": {"target": "group:p", "weight": 1}, "pursue": {"target": "group:f", "weight": 1.3},
         "flee": {"target": "group:p", "radius": 60, "weight": 1}, "catch": {"target": "group:f", "radius": 20, "remove": true},
         "spawn": $rect($s.far, 30)},
        {"name": "a", "prefix": "a", "count": $lvl >= 4 ? $lvl - 3 : 0, "maxSpeed": 120, "maxForce": 300, "radius": 9, "view": 50,
         "separation": 1, "wander": 0.6, "pursue": {"target": "group:f", "weight": 1.5},
         "catch": {"target": "group:f", "radius": 14, "remove": true}, "spawn": $rect($s.far2, 30)},
        {"name": "m", "prefix": "m", "count": 6, "maxSpeed": 18, "maxForce": 40, "radius": 14, "wander": 1, "separation": 1,
         "spawn": [0, 0, $s.W * 32, $s.H * 32]}
      ]
    }
  )};

  /* réglages en direct : éclat (prédateurs repoussés), leurre (prédateurs attirés) */
  $ctl := function($s) {(
    $eclat := $now < $s.eclat.until;
    $leurre := $s.leurre and $now < $s.leurre.until;
    $over := $eclat
      ? {"flee": {"target": "group:p", "radius": 220 * (1 + $s.mods.ample), "weight": 9}, "pursue": {"target": "group:f", "weight": 0}, "flow": {"target": "group:p", "weight": 0}}
      : $leurre
        ? {"pursue": {"target": $s.leurre.at, "weight": 2.4}, "flow": {"target": "group:p", "weight": 0}}
        : {};
    {
      "respawn": $s.respawn,
      "paused": $s.phase != "play",
      "groups": $count($keys($over)) > 0 ? [$merge([{"name": "r"}, $over]), $merge([{"name": "a"}, $over])] : []
    }
  )};

  /* décor : roche explorée, eau vue, trésors et sortie (vus, ou sonar) */
  $decor := function($s) {(
    $tr := $tier($s.level);
    $unseen := $gridFind($s.explored, "0");
    $vis := $gridSet($s.rows, $unseen, "X");
    $rock := $gridContours($s.explored, {"values": "1", "scale": 32, "smooth": 1, "sprites": {"prefix": "e", "fill": $tr.rock, "holeFill": "#020617", "z": 0}});
    $water := $gridContours($vis, {"values": ".", "scale": 32, "smooth": 2, "sprites": {"prefix": "w", "fill": $tr.water, "holeFill": $tr.rock, "z": 10}});
    $seen := function($c) { $s.mods.sonar > 0 or $substring($s.explored[$c[1]], $c[0], 1) = "1" };
    $tre := [$map($filter($s.treasures, function($x) { $seen($x.c) }), function($x) {
      {"name": "t" & $x.id, "shape": "text", "text": "💎", "font-size": 22, "x": $center($x.c)[0], "y": $center($x.c)[1], "z": 40}
    })];
    $ex := $seen($s.exit)
      ? [{"name": "sortie", "shape": "circle", "r": 24, "fill": "#fef08a", "stroke": "#fde047", "line": 4, "opacity": 0.85, "x": $center($s.exit)[0], "y": $center($s.exit)[1], "z": 35},
         {"name": "sortieTxt", "shape": "text", "text": "↑", "font-size": 26, "x": $center($s.exit)[0], "y": $center($s.exit)[1], "z": 36}]
      : [];
    $lu := $s.leurre and $now < $s.leurre.until
      ? [{"name": "leurre", "shape": "text", "text": "🪼", "font-size": 34, "x": $s.leurre.at[0], "y": $s.leurre.at[1], "z": 45}]
      : [];
    [$rock, $water, $tre, $ex, $lu]
  )};

  $withDecor := function($s) { $merge([$s, {"decor": $decor($s), "dirty": false, "fogT": $now}]) };
  $sync := function($s) { $merge([$s, {"ctl": $ctl($s)}]) };

  /* nouvelle partie ou niveau suivant : tout le monde replacé */
  $enter := function($s) {(
    $l := $mkLevel($s);
    $c := $merge($map($names($l.players), function($p) { {$p: $center($l.start)} }));
    $sync($withDecor($merge([$l, {
      "swarm": $spec($l), "respawn": $l.respawn + 1, "cibles": $c, "dirs": {}, "pos": $c,
      "phase": "play", "running": true, "camera": {"x": $center($l.start)[0], "y": $center($l.start)[1], "zoom": 1},
      "sound": $merge([$l.sound, {"music": "calme"}])
    }])))
  )};

  $play := function($s, $name) { $merge([$s, {"sound": $merge([$s.sound, {"play": $merge([$s.sound.play, {$name: ($lookup($s.sound.play, $name) ? $lookup($s.sound.play, $name) : 0) + 1}])}])}]) };

  /* direction d'un joueur (clavier : p0) */
  $DIRS := {"left": [-1, 0], "right": [1, 0], "up": [0, -1], "down": [0, 1]};
  $kb := function($s, $k, $on) {(
    $d := $s.keys ? $s.keys : {};
    $nk := $merge([$d, {$k: $on}]);
    $vx := ($nk.right ? 1 : 0) - ($nk.left ? 1 : 0);
    $vy := ($nk.down ? 1 : 0) - ($nk.up ? 1 : 0);
    $merge([$s, {"keys": $nk, "dirs": $merge([$s.dirs, {"p0": [$vx, $vy]}]), "taps": $merge([$s.taps, {"p0": null}])}])
  )};

  /* rapport de l'essaim : cibles, vision, trésors, sortie, danger, caméra */
  $report := function($s) {(
    $ag := $P.agents;
    $pl := $names($s.players);
    $pos := $merge($map($filter($pl, function($p) { $exists($lookup($ag, $p)) }), function($p) { {$p: [$lookup($ag, $p)[0], $lookup($ag, $p)[1]]} }));
    $cibles := $merge($map($keys($pos), function($p) {(
      $x := $lookup($pos, $p);
      $d := $lookup($s.dirs, $p);
      $n := $d ? $sqrt($d[0] * $d[0] + $d[1] * $d[1]) : 0;
      $tap := $lookup($s.taps, $p);
      {$p: $n > 0.15 ? [$x[0] + $d[0] / $n * 90 * $min([1, $n]), $x[1] + $d[1] / $n * 90 * $min([1, $n])] : $tap ? $tap : $x}
    )}));
    $taps := $merge($map($keys($pos), function($p) {(
      $tap := $lookup($s.taps, $p);
      {$p: $tap and $dist($tap, $lookup($pos, $p)) > 24 ? $tap : null}
    )}));
    /* vision : une case de plus tous les 8 suiveurs */
    $lead := $P.leaders ? $P.leaders : {};
    $key := function($c) { $c[0] & "," & $c[1] };
    $moved := [$filter($keys($pos), function($p) { $key($cellOf($lookup($pos, $p))) != $lookup($s.lastCell, $p) })];
    $explored := $reduce($moved, function($acc, $p) {
      $gridFov($s.rows, $cellOf($lookup($pos, $p)), 4 + 2 * $s.mods.lueur + $min([4, $floor(($lookup($lead, $p) ? $lookup($lead, $p) : 0) / 8)]),
        {"as": "mask", "into": $acc})
    }, $s.explored);
    $lastCell := $merge([$s.lastCell, $merge($map($keys($pos), function($p) { {$p: $key($cellOf($lookup($pos, $p)))} }))]);
    /* trésors */
    $pv := [$map($keys($pos), function($p) { {"x": $lookup($pos, $p)[0], "y": $lookup($pos, $p)[1]} })];
    $near := function($pt, $r) { $count($filter($pv, function($q) { $dist([$q.x, $q.y], $pt) < $r })) > 0 };
    $got := [$filter($s.treasures, function($x) { $near($center($x.c), 30) })];
    $treasures := [$filter($s.treasures, function($x) { $not($x.id in $got.id) })];
    $nGot := $count($got);
    /* sortie */
    $out := $near($center($s.exit), 34);
    /* danger : prédateur à moins de 280 px d'un plongeur */
    $preds := [$filter($keys($ag), function($k) { $substring($k, 0, 1) in ["r", "a"] })];
    $danger := $count($filter($preds, function($k) { $near([$lookup($ag, $k)[0], $lookup($ag, $k)[1]], 280) })) > 0;
    /* caméra : englobe les plongeurs */
    $xs := $pv.x;
    $ys := $pv.y;
    $cam := $count($pv) > 0 ? {
      "x": ($max($xs) + $min($xs)) / 2, "y": ($max($ys) + $min($ys)) / 2,
      "zoom": $max([0.55, $min([1, 860 / ($max($xs) - $min($xs) + 400), 520 / ($max($ys) - $min($ys) + 300)])]),
      "ease": {"ms": 220, "curve": "out"}
    } : $s.camera;
    $fish := $P.groups.f ? $P.groups.f : 0;
    $s2 := $merge([$s, {
      "pos": $pos, "cibles": $cibles, "taps": $taps, "explored": $explored, "lastCell": $lastCell,
      "dirty": $s.dirty or $count($moved) > 0 or $nGot > 0,
      "treasures": $treasures, "score": $s.score + $nGot * 50 * $s.level, "lumiere": $lead, "alive": $fish,
      "camera": $cam,
      "fx": $merge([$s.fx, {"param1": $max([1, $s.fx.param1 * 0.82])}]),
      "sound": $merge([$s.sound, {"music": $danger ? "danger" : "calme"}])
    }]);
    $s3 := $nGot > 0 ? $play($s2, "coin") : $s2;
    $s4 := ($s3.dirty and $now - $s3.fogT > 350) ? $withDecor($s3) : $s3;
    $s5 := $s.phase = "play" and $fish = 0 and $P.groups.p > 0
      ? $play($merge([$s4, {"phase": "over", "running": false, "sound": $merge([$s4.sound, {"music": null}])}]), "gameover")
      : $out
        ? (
            $bonus := $fish * 10;
            $s.level >= 8
              ? $play($merge([$s4, {"phase": "win", "running": false, "score": $s4.score + $bonus, "fish": $fish}]), "levelup")
              : (
                  $sh := $shuffled($UP.id, $s.seed + $s.level * 13);
                  $play($merge([$s4, {"phase": "upgrade", "running": false, "score": $s4.score + $bonus, "fish": $fish,
                    "choix": $map($sh.value[[0 .. 2]], function($id) { $UP[id = $id] })}]), "levelup")
                )
          )
        : $s4;
    $sync($s5)
  )};

  $eclat := function($s, $p) {(
    $ready := $lookup($s.eclat.ready, $p);
    ($s.phase = "play" and ($not($ready) or $now >= $ready))
      ? $sync($play($merge([$s, {
          "eclat": {"until": $now + 1500, "ready": $merge([$s.eclat.ready, {$p: $now + 8000 * (1 - 0.3 * $s.mods.rapide)}])},
          "fx": $merge([$s.fx, {"param1": 3.2}])
        }]), "whoosh"))
      : $s
  )};

  ($t = "start" and $s.phase in ["title", "over", "win"]) ? (
    $seed := $P.daily and $P.value ? $number($join($split($P.value, "-"))) : $floor($now * 1000) % 2147483647;
    $players := $P.players ? $P.players : 1;
    $enter($merge([$s, {
      "players": $players, "replay": {"players": $players}, "seed": $seed, "daily": $P.daily = true, "level": 1, "score": 0,
      "fish": 20 * $players + 10, "mods": {"banc": 0, "lueur": 0, "ample": 0, "rapide": 0, "vif": 0, "leurre": 0, "sonar": 0, "carapace": 0}
    }]))
  ) :
  $t = "swarm:report" ? ($s.phase = "play" ? $report($s) : $s) :
  $t = "swarm:catch" ? (
    $P.group = "f" and $s.phase = "play"
      ? (
          $s.mods.carapace > 0 and $not($s.carapaceUsed)
            ? $sync($play($merge([$s, {"carapaceUsed": true, "fish": $s.fish + 1, "swarm": $merge([$s.swarm, {"groups": $map($s.swarm.groups, function($g) { $g.name = "f" ? $merge([$g, {"count": $g.count + 1}]) : $g })}])}]), "powerup"))
            : $play($s, "hurt")
        )
      : $s
  ) :
  $t in ["left", "right", "up", "down"] ? $kb($s, $t, true) :
  $t in ["left:up", "right:up", "up:up", "down:up"] ? $kb($s, $substringBefore($t, ":"), false) :
  $t = "stick" ? (
    $p := "p" & ($P.pad ? $P.pad : 0);
    $merge([$s, {"dirs": $merge([$s.dirs, {$p: [$P.lx, $P.ly]}]), "taps": $merge([$s.taps, {$p: null}])}])
  ) :
  $t = "pick" ? $merge([$s, {"taps": $merge([$s.taps, {"p0": [$P.x, $P.y]}])}]) :
  $t = "eclat" ? $eclat($s, "p" & ($P.pad ? $P.pad : 0)) :
  $t = "leurre" ? (
    $p := "p" & ($P.pad ? $P.pad : 0);
    $at := $lookup($s.pos, $p);
    ($s.phase = "play" and $s.leurres > 0 and $at)
      ? $sync($withDecor($play($merge([$s, {"leurres": $s.leurres - 1, "leurre": {"at": $at, "until": $now + 5000}}]), "teleport")))
      : $s
  ) :
  $t = "pause" ? (
    $s.phase = "play" ? $sync($merge([$s, {"phase": "pause", "running": false}])) :
    $s.phase = "pause" ? $sync($merge([$s, {"phase": "play", "running": true}])) : $s
  ) :
  $t = "choisir" ? (
    $id := $s.choix[$P.i].id;
    $m := $merge([$s.mods, {$id: $lookup($s.mods, $id) + 1}]);
    $enter($play($merge([$s, {"mods": $m, "level": $s.level + 1, "fish": $id = "banc" ? $s.fish + 15 : $s.fish}]), "powerup"))
  ) :
  $t = "menu" ? $sync($merge([$s, {"phase": "title", "running": false, "sound": $merge([$s.sound, {"music": null}])}])) :
  $s
)

attributes.image:
// Bloom : halo lumineux autour des zones claires de l'image du canal 0 (néons, soleil, étincelles).
// Passe de clarté (seuil) puis flou par échantillonnage en spirale dorée, ajouté à l'image.
// uParam0 seuil (0..1), uParam1 intensité (0..3), uParam2 rayon (en millièmes du petit côté), uParam3 teinte du halo
// (0 = couleur d'origine, 1 = blanc chaud).
vec3 bright(vec2 uv, float th) {
  vec3 col = texture(iChannel0, uv).rgb;
  float l = dot(col, vec3(0.2126, 0.7152, 0.0722));
  return col * smoothstep(th, th + 0.15, l);
}

void mainImage(out vec4 c, in vec2 p) {
  vec2 uv = p / iResolution.xy;
  vec3 base = texture(iChannel0, uv).rgb;
  float th = clamp(uParam0, 0.0, 1.0);
  float radius = max(1.0, uParam2) * 0.001 * min(iResolution.x, iResolution.y);
  vec2 px = 1.0 / iResolution.xy;
  vec3 acc = vec3(0.0);
  float wsum = 0.0;
  for (int i = 0; i < 32; i++) {
    float fi = float(i) + 0.5;
    float r = sqrt(fi / 32.0);
    float a = fi * 2.39996323;
    vec2 o = vec2(cos(a), sin(a)) * r * radius * px;
    float w = 1.0 - r * 0.7;
    acc += bright(uv + o, th) * w;
    wsum += w;
  }
  vec3 glow = acc / wsum;
  glow = mix(glow, vec3(dot(glow, vec3(0.333))) * vec3(1.0, 0.92, 0.8), clamp(uParam3, 0.0, 1.0));
  c = vec4(base + glow * uParam1, 1.0);
}

// Pixel art v5 : l'image du canal 0 redessinée en vrais pixels d'une palette limitée.
// Ordre : couleur cible de chaque pixel d'art, puis tout se décide sur les couleurs de la palette.
// 1. Grille entière ; le plus léger : render-size = résolution d'art + image-rendering: pixelated.
// 2. Représentant : échantillon le plus proche de la moyenne, mêlé (lissage) à un Kuwahara anisotrope
//    à 4 secteurs orienté le long des bords (aplats nets, grain et bruit de photo effacés).
// 3. Étalonnage OKLab : contraste, chroma, ombres vers le bleu-violet, lumières légèrement chaudes.
// 4. Index de palette (OKLab, garde de teinte et de saturation ; gameboy et mac par luminance).
